H.edges[4,8]['weight'] = 4.2

G.degree('B', weight='weight') #total de los atributos del nodo

K = nx.Graph(G) #podemos pasar de un grafico dirigido a uno no dirigido
nx.draw_networkx(K)

"""##**Árbol de expansión Mínima**

Sea $N={1,2,...,n}$ el conjunto de nodos de la red.

$C_k$ el conjunto de nodos qué se han conectado de forma permanente.

$\bar{C_k}$ el conjunto de nodos que no se han conectado.

**algoritmo**

1. Hacer $C_0=\phi \qquad \bar{C_0}=N$

2. Comenzar en algún nodos $i$ de $\bar{C_0}$ e igualar ${C_1}={i}$ y $\bar{C_1}=N-{i}$

3. Seleccionar el nodos $j^* \in \bar{C_{k-1}}$ que produzca el arco más corto a un nodo en $C_{k-1}$.
Enlazar a $j^*$ en forma permanente y sacarlo de $\bar{C_{k-1}}$
"""

import networkx as nx #importamos la librería para generar nuestro árbol de expasión
import matplotlib.pyplot as plt #librería para visualizar el gráfico
#generamos nuestra red con los pesos correspondientes
AME = nx.Graph()
AME.add_edges_from(
    [
        (1, 2, {"weight": 1}),
        (1, 4, {"weight": 7}),
        (1, 5, {"weight": 9}),
        (1, 3, {"weight": 5}),
        (2, 5, {"weight": 3}),
        (2, 3, {"weight": 6}),
        (2, 4, {"weight": 4}),
        (3, 6, {"weight": 10}),
        (3, 4, {"weight": 5}),
        (4, 5, {"weight": 8}),
        (4, 6, {"weight": 3}),
    ]
)

# comando para encontrar el árbol de expansión mínima.
T = nx.minimum_spanning_tree(AME)
print(f"Arcos: {list(T.edges())}")
#imprimimos el peso total del árbol de expansión mínima
peso_total = sum(data['weight'] for u, v, data in T.edges(data=True))
print(f"Peso total del árbol de expansión mínima: {peso_total}")
# Visualizamos el árbol que obtenemos de expansión mínima, resaltandolo en colo distinto al diagrama inicial
pos = nx.spring_layout(AME) #posiciona los nodos para su visualización, asegurándonos de que estén espaciados de forma natural dentro del gráfico
nx.draw_networkx_nodes(AME, pos, node_color="mediumpurple", node_size=500) #resalta los nodos con un color
nx.draw_networkx_edges(AME, pos, edge_color="grey")#identifica los arcos de color gris
nx.draw_networkx_labels(AME, pos, font_size=12, font_family="sans-serif") #imprime los nodos con un tamaño y tipografía específica
nx.draw_networkx_edge_labels(
    G, pos, edge_labels={(u, v): d["weight"] for u, v, d in AME.edges(data=True)}
) #imprime los pesos de los arcos
nx.draw_networkx_edges(T, pos, edge_color="indigo", width=2)#resalta el árbol de expansión obtenido con líneas de otro color y otro grosor.
plt.axis("off")#no muestra ejes al graficar
plt.show()#muestra el gráfico

"""## **Ruta más corta**

**Algoritmo de Dijkastra**

Se basa en definir la etiqueta $[u_j, i] = [u_i + d_{ij}, i], \quad d_{ij}$ donde $u_i$ es la distancia más corta anterior y $d_{ij}$ es la longitud del arco $(i,j)$.

**Paso 0:** Asignar la etiqueta **permanente** $[0, -]$ al nodo 1. Hacer $i = 1$.

**Paso i:**
Calcular las etiquetas temporales $[u_i + d_{ij}, i]$
    
* para cada nodo $j$ al que pueda llegarse desde $i$, siempre y cuando $j$ no
tenga etiqueta permanente.
    
Si $j$ ya tiene etiqueta $[u_j, k]$ por otro nodo $k$ y se cumple que
$u_i + d_{ij} < u_j$, entonces sustituir
$[u_j, k] \quad \text{por} \quad [u_i + d_{ij}, i]$
    
* Si todos los nodos tienen etiquetas permanentes, detenerse.
    
En otro caso: seleccionar la etiqueta $[u_r, s]$ que tenga la distancia más corta $u_r$ entre todas las etiquetas temporales (los empates se rompen en forma arbitraria).

Hacer $i=r$ y repetir el paso $i$
"""

import networkx as nx
import matplotlib.pyplot as plt

# Crear un grafo dirigido
RMC = nx.DiGraph()

# Agregar nodos y aristas con pesos
RMC.add_edge('A', 'B', weight=2)
RMC.add_edge('A', 'C', weight=5)
RMC.add_edge('B', 'C', weight=3)
RMC.add_edge('C', 'D', weight=1)
RMC.add_edge('C', 'E', weight=4)
RMC.add_edge('D', 'B', weight=4)
RMC.add_edge('D', 'E', weight=4)

# Encontrar la ruta más corta usando el algoritmo de Dijkstra
ruta_mas_corta = nx.shortest_path(RMC, source='A', target='E', weight='weight')
print(f"La ruta más corta de A a F es: {ruta_mas_corta}")
# Imprime la longitud de la ruta mas corta
print(f"Longitud de la ruta más corta: {nx.shortest_path_length(RMC, source='A', target='E', weight='weight')}")
# Crear listas de aristas para resaltar la ruta más corta
aristas_ruta = [(ruta_mas_corta[i], ruta_mas_corta[i+1])
                for i in range(len(ruta_mas_corta)-1)]

# Configurar la visualización
plt.figure(figsize=(10, 8))

# Definir posición de los nodos
pos = nx.spring_layout(RMC)

# Dibujar el grafo completo
nx.draw_networkx_nodes(RMC, pos, node_size=500, node_color='mediumpurple')
nx.draw_networkx_edges(RMC, pos, edge_color='gray', arrows=True,
                      arrowstyle='->', arrowsize=20)
nx.draw_networkx_labels(RMC, pos, font_size=16)
# visualizar las etiquetas de los pesos
edge_labels = nx.get_edge_attributes(RMC, 'weight')
nx.draw_networkx_edge_labels(RMC, pos, edge_labels=edge_labels)

# Resaltar la ruta más corta
nx.draw_networkx_edges(RMC, pos, edgelist=aristas_ruta,
                      edge_color='indigo', width=3, arrows=True,
                      arrowstyle='->', arrowsize=25)

# Resaltar los nodos de la ruta más corta
nx.draw_networkx_nodes(RMC, pos, nodelist=ruta_mas_corta,
                      node_size=600, node_color='purple')

plt.axis('off')
plt.show()

"""## **Flujo Máximo**


"""

#importamos las paqueterías necesarias
import networkx as nx
import matplotlib.pyplot as plt
#definimos el tipo de grafo
FM = nx.Graph()
#agregamos los nodos con su capacidad de flujo
FM.add_edges_from(
    [
        (1, 2, {"capacity": 1}),
        (1, 4, {"capacity": 7}),
        (1, 5, {"capacity": 9}),
        (1, 3, {"capacity": 5}),
        (2, 5, {"capacity": 3}),
        (2, 3, {"capacity": 6}),
        (2, 4, {"capacity": 4}),
        (3, 6, {"capacity": 10}),
        (3, 4, {"capacity": 5}),
        (4, 5, {"capacity": 8}),
        (4, 6, {"capacity": 3}),
    ]
)
#determina el flujo máximo del grafo, dado los nodos iniciales y finales que se indiquen
flow_value, flow_dict = nx.maximum_flow(FM, 1, 6)
print(f"Flujo máximo: {flow_value}")
# Lista de todas las aristas con flujo
flujo_recorrido = []
for u in sorted(flow_dict.keys()):
    for v in sorted(flow_dict[u].keys()):
        if flow_dict[u][v] > 0:
            flujo_recorrido.append((u, v, flow_dict[u][v]))
            print(f"{u} → {v}: {flow_dict[u][v]} unidades")

print(f"\nTotal de aristas con flujo: {len(flujo_recorrido)}")
# Diseño del grafo
pos = nx.spring_layout(FM, seed=42)

# Dibujar nodos
nx.draw_networkx_nodes(FM, pos, node_color='mediumpurple',
                      node_size=500, alpha=0.9)

# Visualizar etiquetas de nodos
nx.draw_networkx_labels(FM, pos, font_size=12)

# Dibujar aristas con etiquetas de capacidad y flujo
edge_labels = {}
for u in FM.nodes():
    for v in FM.nodes():
        if FM.has_edge(u, v):
            capacity = FM[u][v]['capacity']
            # Obtener el flujo (puede ser en cualquier dirección para grafos no dirigidos)
            flow = flow_dict.get(u, {}).get(v, 0) or flow_dict.get(v, {}).get(u, 0)
            edge_labels[(u, v)] = f'{flow}/{capacity}'
# Visualizar las aristas
nx.draw_networkx_edges(FM, pos, edge_color='gray',
                      width=2, alpha=0.7, arrows=True)

# Visualizar las etiquetas de aristas
nx.draw_networkx_edge_labels(FM, pos, edge_labels=edge_labels,
                           font_color='purple', font_size=8)

plt.axis('off')
plt.show()

